def power(a, b):
    # Compute a to the power of b using fast exponentiation
    ans = 1
    while b > 0:
        if b % 2:
            ans = ans * a
        a = a * a
        b //= 2
    return ans


def factorial_mod(n, p=998244353):
    # Compute factorial of n modulo p
    ans = 1
    fact = 1
    for i in range(1, n + 1):
        ans *= i
        ans %= p
        fact = fact * i
        fact %= p
    return ans * power(fact, p - 2)


class HGHTree:
    def __init__(self, n):
        self.n = n
        self.resize()

    def resize(self):
        self.arr = [3] * (self.n + 1)

    def update_edge(self, start, middle, end):
        if self.arr[len(start)] == 3 and self.arr[len(middle)] == 3:
            # Middle node with 3 edges is not possible in a Hagh tree
            return False
        if self.arr[len(start)] == 1:
            # Edge not possible
            return False
        # Adjust edge count and update vertex count
        for i in range(len(start)):
            if len(start[:i] + (self.arr[len(start)] - self.arr[i], ) + start[i + 1:]) > self.n:
                # Operation not possible due to edge count
                return False
        for i in range(len(middle)):
            if len(middle[:i] + (self.arr[len(middle[i])], ) + middle[i + 1:]) > self.n:
                # Operation not possible due to edge count
                return False
        for i in range(len(end)):
            if len(end[:i] + (self.arr[len(end[i]) - 1 if i - 1 >= 0 else 0], ) + end[i + 1:]) > self.n:
                # Operation not possible due to edge count
                return False
        return True


def solve(n):
    G = HGHTree(n)
    ans = 1
    # Edge limiting is (n - 3)^n + (n - 1)**n + 1
    for i in range(n + 1):
        for j in range(n + 1):
            for k in range(n + 1):
                if G.update_edge([i, j, k], [i, j], [j, k]):
                    ans = (ans * factorial_mod((i + j + k) - 6)) % 998244353 * power(3, (i + j + k) - 6, 998244353) % 998244353
    return (ans * power(3 ** 3)) % 998244353
