import sys
from collections import deque

class Graph:
    def __init__(self, n):
        self.graph = {i: set() for i in range(1, n + 1)}

    def add_edge(self, u, v):
        self.graph[u].add(v)

    def dfs(self, i, parent):
        for j in self.graph[i]:
            if j != parent:
                self.dfs(j, i)
                self.res[i] += 1
                self.res[j] += 1

    def get_num_of_components(self):
        self.res = [0 for _ in range(len(self.graph) + 1)]
        for i in range(1, len(self.graph) + 1):
            if self.res[i] == 0:
                self.dfs(i, -1)
                priorityq = deque([(i, 0)])
                while priorityq:
                    u, count = priorityq.popleft()
                    count += 1
                    for v in self.graph[u]:
                        if self.res[v] == 0:
                            priorityq.append((v, count))
                            self.res[v] += 1
        return len(self.res)

if __name__ == "__main__":
