def dijkstra(n, rectangles, start_row, start_col):
    row_sets = [-start_row]
    col_sets = [-start_col]
    rows, cols = [], []
    costs = {point: float('inf') for point in row_sets + col_sets + rows + cols}
    costs[start_row, start_col] = 0
    points = row_sets + col_sets
    heapq.heappush(points, (0, start_row, start_col))
    total_cost = float('inf')

    while points:
        cost, r, c = heappop(points)
