class UnionFind:
    def __init__(self, n):
        self.sets = set()
        for i in range(n):
            self.sets.add((i, i))

    def find_set(self, x):
        if x != self.sets[x][0]:
            self.sets[x] = self.find_set(self.sets[x][0])
        return self.sets[x][0]

    def union_set(self, x, y):
        if x == y:
            return False

        x_root = self.find_set(x)
        y_root = self.find_set(y)

        if x_root == y_root:
            return False

        # Union operation
        for i in self.sets:
            if i[1] == x_root:
                i[0] = x_root
            elif i[1] == y_root:
                i[0] = y_root

        self.sets.add((x, y))

        return True

    def find_sets(x):
        return {self.find_set(x)}

