from collections import deque
import sys

def bfs(grid, start, end):
    queue = deque([(start, 0)])
    visited = set([start])
    while queue:
        (x, y), cost = queue.popleft()
        if (x, y) == end:
            return cost, visited
        for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nx, ny = x + dx, y + dy
            if 0 <= nx < n and 0 <= ny < n and (nx, ny) not in visited and grid[nx][ny]:
                queue.append(((nx, ny), cost + 1 + abs(n - nx - ny)))
                visited.add((nx, ny))
    return sys.maxsize, visited

n = int(sys.stdin.readline().strip())
m = int(sys.stdin.readline().strip())
grid = [list(map(int, sys.stdin.readline().strip().split())) for _ in range(n)]

start = (0, 0)
min_cost = sys.maxsize
for i in range(m):
    part = [int(j) for j in sys.stdin.readline().strip().split()]
    for j in range(part[1] - part[0], n):
        for k in range(part[0], part[2]):
            grid[j][k] = 1
    cost, visited = bfs(grid, start, (n - 1, n - 1))
    if cost < min_cost:
        min_cost = cost
    for j in range(part[1] - part[0], n):
        for k in range(part[0], part[2]):
            grid[j][k] = 0

