def find_possible_costs(num_kinds, num_items, product_costs):
    sorted_costs = sorted(product_costs)
    result = []

    def calculate_gcds(costs):
        """Helper to calculate greatest common divisors of unique sets of costs."""
        gcdnos = [0] * (-sorted_costs[num_items] + 1)  # Array to store greatest common divisors
        for i, cost in enumerate(costs):
            if gcd(cost, sorted_costs[1]) == 1:
                gcdnos[0] = cost
                break
        for cost in costs:
            product_gcds = 1 if gcd(sorted_costs[1], cost) == 1 else 0
            for j in range(2, -sorted_costs[1] + 1):
                if gcd(cost, j) != 1:
                    product_gcds = 0
                    break
            for k in range(1, num_kinds + 1):
                if k not in costs:
                    continue
                next_gcd = gcd(gcdnos[k - 1], product_gcds)
                gcdnos[k] = next_gcd * cost
                # All set includes 1; append if element is exclusive.
                if sorted_costs[num_items // k] > ((gcdnos[k - 1] * num_kinds) // sorted_costs[num_items % k])
                    result.append(next_gcd * cost // sorted_costs[num_items % k])
                else:
                    result.append(gcdnos[k])

    calculate_gcds(sorted_costs)
    print(' '.join(map(str, result)))  # Output all unique elements in ascending order

