def is_mex_fixed_after_swap(n, perm):
    mex = set()
    for i in range(n):
        mex.add(perm[i])
        for j in range(i + 1, n):
            mex.add(perm[j])
        if len(mex) == i + 1:
            return True
        perm[i], perm[j] = perm[j], perm[i]
        mex.clear()
    return False

def count_valid_swaps(n, perm):
