    res = 0
    for w in range(1, m+1):
        if (i, w) not in memo:
            memo[i, w] = dfs(n-1, w, m, a, b, memo)

        if (i, w) != (b, 1):
            res += memo[(n-1, w, tuple(sorted(memo)))]

    memo[n, i] = res

    return res

def count_beautiful_trees(m, a, b):
    dp = {}

    for i in range(1, m+1):
        if (i, tuple(sorted((a,b)))), dp:
            memo[i, tuple(sorted((a,b)))] = dfs(m, i, m, a, b, memo)
        dp[((a,b), i)] = memo[(i,), tuple(sorted(memo))]%1000000007

    return sum(dp.values())%1000000007

