                if (s[i], s[j]) not in d[j]:
                    d[j] += [(s[i], s[j])]
                s = s[i], s[j]
                continue
            for k in d[j]:
                if k[1] <= i or k[0] <= j:
                    break
                else:
                    if s[i-1] == s[j-1]:
                        len_ = min(k[1], k[0]) + i + j - 2
                        len_lst = [(len_, i + j + 1)]
                        if len(k[1]) == j - i:
                            len_lst = [(len_, i + j)]
                        additionally = [fst[1] for fst in d[i] if fst[0] >= k[1]]
                        for addfst in additionally:
                            if addfst + k[1] <= len(m):
                                if k[0] + addfst + i + j - 2 + len(fst[1]) <= len(m) - 1:
                                    len_lst += [[i + j + addfst + k[1] - 1, addfst + k[1] - 1 + i + j - 2 + len(fst[1])]]
                                    if addfst + k[1] > len(fst[1]):
                                        len_lst += [(0, i + j + addfst + k[1] - 1 + i + j - 2 + len(fst[1]))]
                                else:
                                    break
                        if i + j + k[1] <= len(m) - 1:
                            len_lst += [[i + j, i + j + k[1]]]
                        d[k[1]] = len_lst
    return len(m) - 1, min(j for j in d[min(d.keys(), key=lambda k: d[k][0])][1]) - max(1, i)
