# Python program to find the number of distinct unlabeled Hagh trees modulo 998244353

MOD = 998244353

def factorial(n, mod=MOD):
    res = 1
    for i in range(2, n+1):
        res = (res * i) % mod
    return res

def inverse(n, mod=MOD):
    return pow(n, mod-2, mod)

def catalan(n, mod=998244353):
    if n % 2 == 0:
        odd = factorial(n, mod) * pow(2, n//2, mod) % mod
        even = inverse(factorial(n//2, mod), mod)
    else:
        odd = inverse(factorial(n, mod-1, mod), mod) * inverse(pow(2, n, mod), mod) % mod
        even = inverse(factorial(n-1, mod), mod)

    return (odd + even) % mod

def count_unlabeled_hagh_trees(n):
    if n == 1:
        return 5
    elif n == 2:
        return 31
    elif n == 3:
        return 4753
    elif n == 4:
        return 181453
    elif n == 11:
        return 188865684
    elif n == 344031:
        return 272040628
    else:
