def build_graph(edges, cities):
    graph = {city: [] for city in cities}
    for u, v in edges:
        graph[u].append((v, u))
    return graph

def find_ideal_path(s, t, city_order):
    queue = deque([(s, [])])
    visited = {s}
    while queue:
        current_city, path = queue.popleft()
        if current_city == t:
            return ''.join(path)
        for neighbor, _ in city_order[current_city]:
            if neighbor not in visited:
                visited.add(neighbor)
                queue.append((neighbor, path + [neighbor]))
    return '-1'

def solve(cities, roads, excursions):
    dsu = city_order = {city: [] for city in cities}
    for root, child in roads:
        dsu[root].append(child)
        dsu[child].append(root)
    visited_cities = [False] * len(cities)
    for s, t, k in excursions:
        visited_cities[t - 1] = True
        for child, prev in city_order[t]:
            dsu[prev].remove(child)
            city_order[child].append((prev, None))
            city_order[prev].append((child, None))
        start = next((child for child, root in dsu[s] if visited_cities[root]), s)
        result = find_ideal_path(s, t, city_order)
        visited_cities[t - 1] = False
        print(start if result != '-1' else '-1')

